def _enr_rows():
    out=[]
    for art,e in ENR42['results'].items():
        for mk,v in (e.get('markers') or {}).items():
            out.append([art,mk,f"{v['enrichment']:.3f}×",f"p={v['p_value']:.3f}",
                        'PASS' if v['passes'] else 'fail'])
    return out
H42_ENR_ROWS=_enr_rows()
def _uni_max(art):
    r=UNI42.get(art) or {}
    return max((v['jaccard'] for v in r.values()), default=0.0) if r else 0.0
H42_UNI_MAX=max(_uni_max(a) for a in UNI42) if UNI42 else 0.0
