rows=[];current=None;seen=set()
for line in brief.splitlines():
    m=re.search(r'https://buffedlizard55-lab.github.io/([^/]+)/',line)
    if m:current=m.group(1)
    match=re.fullmatch(r'([A-Za-z0-9_][A-Za-z0-9_.-]+):\s*(0\.\d+)?',line.strip())
    if match and current:
        key=(current,match.group(1))
        if key not in seen:
            rows.append([current,match.group(1),match.group(2) or '', 'user-reported; not independently artifact-authenticated']);seen.add(key)
